"""Guardrails over the SQL generated by the LLM, before running it."""
import re

FORBIDDEN_KEYWORDS = ["INSERT", "UPDATE", "DELETE", "DROP", "ALTER", "TRUNCATE", "CREATE"]


def is_sql_safe(sql: str) -> bool:
    sql_upper = sql.upper()
    return not any(keyword in sql_upper for keyword in FORBIDDEN_KEYWORDS)


def strip_markdown(sql: str) -> str:
    return re.sub(r"^```sql|```$", "", sql, flags=re.MULTILINE).strip()


def enforce_limit_from_question(sql: str, question: str) -> str:
    """If the question asks for a concrete number ('top 10', '5 terms'), force
    that exact LIMIT in the SQL, without relying on the LLM to honor it."""
    match = re.search(r"\btop\s+(\d+)\b", question.lower())
    if not match:
        match = re.search(
            r"\b(\d+)\s+(terms|results|instances|categories|searches|rows|products)\b",
            question.lower(),
        )
    if match:
        number = match.group(1)
        if re.search(r"\bLIMIT\s+\d+", sql, flags=re.IGNORECASE):
            sql = re.sub(r"\bLIMIT\s+\d+", f"LIMIT {number}", sql, flags=re.IGNORECASE)
        else:
            sql = sql.rstrip(";").rstrip() + f" LIMIT {number}"
    return sql
